//! Frozen circuit versions, as generated by `noir-zk-codegen` from a
//! `noir-zk freeze` manifest.

use crate::zk::ProofSystem;

/// Lifecycle of a frozen circuit version.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Status {
    /// Proves and verifies.
    Active,
    /// Superseded: its key is kept, its ABI dropped.
    Deprecated,
}

/// One frozen circuit version.
#[derive(Clone, Copy, Debug)]
pub struct RegistryEntry {
    /// Circuit package name.
    pub label: &'static str,
    /// Frozen version.
    pub version: &'static str,
    /// Which proof system proves it.
    pub system: ProofSystem,
    /// Lifecycle status.
    pub status: Status,
    /// SHA-256 of the base64 bytecode (the release asset's content).
    pub bytecode_sha256: [u8; 32],
    /// SHA-256 of the verification key ([`RegistryEntry::vk`], a pack's
    /// `.vk` file).
    pub vk_sha256: [u8; 32],
    /// Poseidon2 hash of the key as fields (`H(vk fields)`, big-endian): the
    /// family trees' leaf.
    pub vk_hash: [u8; 32],
    /// The layer and family this circuit belongs to (`""` for circuits
    /// outside any family, such as UltraHonk ones).
    pub layer: &'static str,
    /// The family.
    pub family: &'static str,
    /// nargo's ABI JSON (active versions only).
    pub abi: Option<&'static str>,
    /// Verification key.
    pub vk: &'static [u8],
    /// Leaf index in the verification key tree (active, non-hiding circuits).
    pub vk_index: Option<u64>,
    /// Tree siblings from the leaf up (big-endian field elements).
    pub vk_siblings: &'static [[u8; 32]],
}

impl RegistryEntry {
    /// Release asset name of this version's bytecode.
    pub fn asset_name(&self) -> String {
        format!("{}@{}.b64", self.label, self.version)
    }
}

/// A registry's library: the name and version its families are identified by.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Library {
    /// The library's name.
    pub name: &'static str,
    /// Its version.
    pub version: &'static str,
}

/// The active version of `label` in `registry`.
pub fn active<'a>(registry: &'a [RegistryEntry], label: &str) -> Option<&'a RegistryEntry> {
    registry
        .iter()
        .find(|e| e.label == label && e.status == Status::Active)
}
